nch_code ), final_data as ( select sales_inv.*, category.category from sales_inventory_data as sales_inv left join category as category on sales_inv.sku_group = category.sku_group where sales_inv.sku_class is not null ) select *, case when lower(sku_group) like \'4mbg%\' then \'plus_size\' when lower(category) in (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\') then \'long_tail\' else \'none\' end as l1_category from final_data",
